import ts from 'typescript';
import * as esbuild from 'esbuild-wasm';
import wasmURL from 'esbuild-wasm/esbuild.wasm?url';
let initialization;
async function initialized(){if(!initialization)initialization=esbuild.initialize({wasmURL}).catch(error=>{initialization=undefined;throw error;});await initialization;}
export async function transform({source,target,compiler='typescript'}){
  if(!['es2015','es2020'].includes(target))throw Error('Unsupported target');
